// FILE: frontend/src/App.js
//
// --- VERSION 1.9.0 ---
// - Added new route for the "LogPlayback" page.
// -----------------------------

import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import Header from './components/layout/Header';
import Footer from './components/layout/Footer';
import LogList from './components/pages/LogList';
import LogDetail from './components/pages/LogDetail';
import TripGroupDetail from './components/pages/TripGroupDetail';
import LogPlayback from './components/pages/LogPlayback'; // Import the new component
import './App.css';

function App() {
  const [theme, setTheme] = useState('dark');

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => prevTheme === 'dark' ? 'light' : 'dark');
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-base-200 text-base-content">
        <Header theme={theme} toggleTheme={toggleTheme} />
        <main className="flex-grow container mx-auto p-4">
          <Routes>
            <Route path="/" element={<LogList />} />
            <Route path="/logs/:logId" element={<LogDetail />} />
            <Route path="/trip-groups/:groupId" element={<TripGroupDetail />} />
            {/* Add the new route for the playback feature */}
            <Route path="/playback/:logId" element={<LogPlayback />} />
            <Route path="*" element={
              <div>
                <h2>404 Not Found</h2>
                <Link to="/">Go Home</Link>
              </div>
            } />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
